Tool response:
Tool: mark_doctor_unavailable
Description: Marks the specified doctor as unavailable for the given date range. This operation will also reassign all scheduled appointments for that doctor on those dates to another available doctor.
Parameters:
    {
      "type": "object",
      "properties": {
        "doctor_id": {
          "type": "integer",
          "description": "Internal ID of the doctor to mark as unavailable",
          "title": "Doctor Id"
        },
        "start_date": {
          "type": "string",
          "description": "Start date of unavailability period (YYYY-MM-DD)",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "description": "End date of unavailability period (YYYY-MM-DD)",
          "title": "End Date"
        },
        "reason": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Reason for unavailability",
          "title": "Reason"
        },
        "replacement_doctor_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "ID of the doctor to whom appointments should be reassigned.",
          "title": "Replacement Doctor Id"
        }
      },
      "required": [
        "doctor_id",
        "start_date",
        "end_date"
      ]
    }

Tool response:
Tool: find_doctors
Description: Retrieve a list of doctors with their IDs, names, specialties, and license numbers.
Parameters:
    {
      "type": "object",
      "properties": {
        "full_name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Full name of the doctor to search for",
          "title": "Full Name"
        },
        "specialty": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Specialty of the doctor to search for",
          "title": "Specialty"
        }
      },
      "required": []
    }
